  ["Spell names under icons"] = "Zaubernamen unter den Symbolen",
  ["Spells & trinkets"] = "Zauber & Schmuckstücke",
  ["Spells & trinkets: untick a spell or trinket to never see it, or tick First when ready to put a spell in slot 1 whenever it can be cast. Kept per spec, through updates."] = "Zauber & Schmuckstücke: entferne den Haken bei einem Zauber oder Schmuckstück, um es nie zu sehen, oder hake Zuerst, wenn bereit an, um einen Zauber in Feld 1 zu setzen, sobald er gewirkt werden kann. Pro Spezialisierung gespeichert, auch über Updates.",
  ["Spells in the list you don't have (or we can't match): %s"] = "Zauber der Liste, die du nicht hast (oder die wir nicht zuordnen können): %s",
  ["Spells matched: %s. Type /dmga help for options."] = "Zugeordnete Zauber: %s. Gib /dmga help für Optionen ein.",
  ["Spells of the rotation you have"] = "Zauber der Rotation, die du hast",
