  ["Steady"] = "Gleichmäßig",
  ["Store a decision snapshot"] = "Entscheidungs-Momentaufnahme speichern",
  ["Suggest a defensive this long before a big hit that a boss mod announces."] = "Einen Verteidigungszauber so lange vor einem großen Treffer vorschlagen, den ein Boss-Addon ankündigt.",
