  ["Trinkets"] = "Schmuckstücke",
  ["Troubleshooting"] = "Fehlersuche",
  ["Two-spell branches"] = "Zwei-Zauber-Verzweigungen",
  ["Unlock to drag the icons; they are also shown while this panel is open."] = "Lösen, um die Symbole zu ziehen; sie werden auch angezeigt, solange dieses Fenster offen ist.",
  ["Upcoming adds, AoE, tank hits and interrupts: used for defensives, interrupts and SimC's add timing."] = "Kommende Adds, Flächenschaden, Tanktreffer und Unterbrechungen: genutzt für Verteidigung, Unterbrechungen und SimCs Add-Timing.",
  ["Use a profile for this character only"] = "Ein Profil nur für diesen Charakter nutzen",
  ["Use cooldowns on"] = "Abklingzeiten nutzen bei",
  ["Use the suggestions"] = "Die Empfehlungen nutzen",
  ["Used when \"AoE target count\" is Custom: this many targets or more counts as AoE."] = "Gilt, wenn „Ab wie vielen Zielen Flächenschaden\" auf Eigene steht: ab so vielen Zielen gilt es als Fläche.",
  ["Used when the count isn't available. The key binding switches during a fight."] = "Gilt, wenn die Zahl nicht verfügbar ist. Die Tastenbelegung wechselt während eines Kampfes.",
  ["Version"] = "Version",
  ["Warn about missing keybinds"] = "Vor fehlenden Tastenbelegungen warnen",
  ["Warning: data for %s loaded at once; using %s."] = "Warnung: Daten für %s gleichzeitig geladen; verwende %s.",
  ["Watchdog (diagnostics)"] = "Watchdog (Diagnose)",
  ["Welcome to DMGAssist"] = "Willkommen bei DMGAssist",
  ["What were you doing? (for example: 5 dummies, a Mythic+ pull, a raid boss, solo)"] = "Was hast du gemacht? (zum Beispiel: 5 Puppen, ein Mythisch+-Pull, ein Schlachtzugsboss, solo)",
  ["When"] = "Wann",
  ["When a hidden resource decides (e.g. 4 or 5 combo points), show both spells; the game makes the right one visible."] = "Wenn eine verborgene Ressource entscheidet (z. B. 4 oder 5 Combopunkte), beide Zauber zeigen; das Spiel macht den richtigen sichtbar.",
  ["When should it show?"] = "Wann soll es erscheinen?",
  ["When to show"] = "Wann anzeigen",
  ["When your boss mod warns of AoE damage, show Power Word: Radiance, then Shield, until enough Atonements are up."] = "Wenn dein Boss-Addon vor Flächenschaden warnt, Machtwort: Glanz und dann Schild zeigen, bis genug Abbitten aktiv sind.",
  ["Where should the recommendations go?"] = "Wohin sollen die Empfehlungen?",
  ["Where the rotation comes from"] = "Woher die Rotation stammt",
  ["Where the small badge for spells pressed alongside slot 1 (no GCD, e.g. Ironfur) sits."] = "Wo das kleine Abzeichen für Zauber sitzt, die neben Feld 1 gedrückt werden (ohne GCD, z. B. Eisenfell).",
  ["Whisper"] = "Flüstern",
  ["With \"Bosses and big pulls\": this many enemies or more counts as a big pull."] = "Mit „Bosse und große Pulls\": ab so vielen Gegnern gilt ein Pull als groß.",
  ["With DBM, BigWigs or LittleWigs, a defensive is shown a few seconds before a big hit they warn about (lighter ones first; on cooldown, the next). Also when you are low. Integrations has buttons to test both."] = "Mit DBM, BigWigs oder LittleWigs wird ein Verteidigungszauber ein paar Sekunden vor einem großen Treffer gezeigt, vor dem sie warnen (leichtere zuerst; in Abklingzeit der nächste). Auch bei niedrigem Leben. Unter Integrationen kannst du beides testen.",
  ["With a controller (the game's gamepad support), keybinds show as controller buttons, for example LT+A."] = "Mit einem Controller (der Gamepad-Unterstützung des Spiels) erscheinen Tastenbelegungen als Controllertasten, zum Beispiel LT+A.",
  ["Xbox (A B X Y, LB RB)"] = "Xbox (A B X Y, LB RB)",
  ["You have unspent talent points: press N to open your talents."] = "Du hast unverteilte Talentpunkte: drücke N, um deine Talente zu öffnen.",
  ["You know enough of this spec's spells now: DMGAssist's priority list leads."] = "Du kennst jetzt genug Zauber dieser Spezialisierung: die Prioritätenliste von DMGAssist führt.",
  ["Your choices"] = "Deine Auswahl",
  ["Your spec's switch point"] = "Umschaltpunkt deiner Spezialisierung",
  ["Your spec's switch point comes from its SimC list (when it uses an AoE list): the count where it changes."] = "Der Umschaltpunkt deiner Spezialisierung kommt aus ihrer SimC-Liste (wenn sie eine Flächenliste nutzt): die Zahl, bei der sie wechselt.",
  ["available (used as a second opinion)"] = "verfügbar (als zweite Meinung genutzt)",
  ["held"] = "zurückgehalten",
  ["installed"] = "installiert",
  ["learned"] = "gelernt",
  ["learning: SimC default for now"] = "lernt: vorerst SimC-Standard",
  ["leveling: following Blizzard's Assisted Combat until you know more of this spec's spells"] = "Leveln: folgt Blizzards Kampfassistent, bis du mehr Zauber dieser Spezialisierung kennst",
  ["manual"] = "manuell",
  ["no"] = "nein",
  ["no SimC list for this spec: DMGAssist's own list, learned from the class guides"] = "keine SimC-Liste für diese Spezialisierung: DMGAssists eigene Liste, gelernt aus den Klassenguides",
