  ["trinket, top slot"] = "Schmuckstück, oberer Platz",
  ["yes"] = "ja",
  ["|cffffd100Step 1.|r What went wrong? What did you expect instead?"] = "|cffffd100Schritt 1.|r Was ist schiefgegangen? Was hättest du stattdessen erwartet?",
  ["|cffffd100Step 2.|r Click the box below and press |cffffffffCtrl+C|r. Your words above are included."] = "|cffffd100Schritt 2.|r Klick in das Feld unten und drücke |cffffffffStrg+C|r. Deine Worte oben sind enthalten.",
  ["|cffffd100Step 3.|r Open this page in your browser (click it, Ctrl+C, paste it in the address bar),"] = "|cffffd100Schritt 3.|r Öffne diese Seite in deinem Browser (anklicken, Strg+C, in die Adressleiste einfügen),",
